DROP VIEW IF EXISTS v_prealertas;
CREATE VIEW v_prealertas AS WITH prm AS ( SELECT volumen_minimo, julianday(COALESCE(ahora, 'now')) AS ahora_jd FROM alerta_parametros WHERE id = 1 ), c AS ( SELECT o.ambiente, o.cliente_id, o.servicio_id, o.producto_id, o.canal_id, o.moneda_id, o.duracion_ventana_minutos, strftime('%Y-%m-%dT%H:%M:%SZ', o.ventana_inicio) AS ventana_inicio, strftime('%Y-%m-%dT%H:%M:%SZ', o.ventana_fin) AS ventana_fin, o.cantidad_total, 1.0 * o.cantidad_exitos / NULLIF(o.cantidad_total, 0) AS aprob, 1.0 * o.cantidad_rechazos / NULLIF(o.cantidad_total, 0) AS rech, 1.0 * o.cantidad_errores / NULLIF(o.cantidad_total, 0) AS err, o.tiempo_respuesta_promedio AS lat, p.cantidad_total_esperada, p.cantidad_total_minima, p.tasa_aprobacion_esperada, p.tasa_aprobacion_minima, p.tasa_rechazo_esperada, p.tasa_rechazo_maxima, p.tasa_error_esperada, p.tasa_error_maxima, p.tiempo_respuesta_esperado, p.tiempo_respuesta_maximo, (p.cantidad_total_esperada - o.cantidad_total) / NULLIF(p.cantidad_total_esperada - p.cantidad_total_minima, 0) AS m_vol, CASE WHEN o.cantidad_total >= prm.volumen_minimo THEN (p.tasa_aprobacion_esperada - 1.0 * o.cantidad_exitos / o.cantidad_total) / NULLIF(p.tasa_aprobacion_esperada - p.tasa_aprobacion_minima, 0) END AS m_aprob, CASE WHEN o.cantidad_total >= prm.volumen_minimo THEN (1.0 * o.cantidad_rechazos / o.cantidad_total - p.tasa_rechazo_esperada) / NULLIF(p.tasa_rechazo_maxima - p.tasa_rechazo_esperada, 0) END AS m_rech, CASE WHEN o.cantidad_total >= prm.volumen_minimo THEN (1.0 * o.cantidad_errores / o.cantidad_total - p.tasa_error_esperada) / NULLIF(p.tasa_error_maxima - p.tasa_error_esperada, 0) END AS m_err, CASE WHEN o.cantidad_total >= prm.volumen_minimo THEN (o.tiempo_respuesta_promedio - p.tiempo_respuesta_esperado) / NULLIF(p.tiempo_respuesta_maximo - p.tiempo_respuesta_esperado, 0) END AS m_lat FROM core_metricas_observadas o CROSS JOIN core_metricas_esperadas p CROSS JOIN prm WHERE p.ventana_inicio = strftime('%Y-%m-%dT%H:%M:%fZ', o.ventana_inicio) AND p.duracion_ventana_minutos = o.duracion_ventana_minutos AND p.ambiente = o.ambiente AND p.cliente_id = o.cliente_id AND p.servicio_id = o.servicio_id AND p.producto_id = o.producto_id AND p.canal_id = o.canal_id AND p.moneda_id = o.moneda_id AND p.estado_prediccion = 'ACTIVA' AND NOT EXISTS ( SELECT 1 FROM core_metricas_esperadas p2 WHERE p2.ventana_inicio = p.ventana_inicio AND p2.duracion_ventana_minutos = p.duracion_ventana_minutos AND p2.ambiente = p.ambiente AND p2.cliente_id = p.cliente_id AND p2.servicio_id = p.servicio_id AND p2.producto_id = p.producto_id AND p2.canal_id = p.canal_id AND p2.moneda_id = p.moneda_id AND p2.estado_prediccion = 'ACTIVA' AND ( julianday(p2.fecha_generacion) > julianday(p.fecha_generacion) OR ( julianday(p2.fecha_generacion) = julianday(p.fecha_generacion) AND p2.modelo_version > p.modelo_version ) ) ) AND o.ventana_inicio >= (SELECT strftime('%Y-%m-%dT%H:%M:%S', COALESCE(ahora, 'now'), '-49 hours') FROM alerta_parametros WHERE id = 1) AND julianday(o.ventana_fin) <= prm.ahora_jd AND o.cantidad_total > 0 ), t AS ( SELECT c.*, LAG(c.ventana_inicio, 2) OVER s AS ventana_inicio_2, MAX(c.ventana_inicio) OVER (PARTITION BY c.ambiente, c.cliente_id, c.servicio_id, c.producto_id, c.canal_id, c.moneda_id, c.duracion_ventana_minutos) AS ultima_ventana_serie, LAG(c.m_vol, 1) OVER s AS m_vol_1, LAG(c.m_vol, 2) OVER s AS m_vol_2, LAG(c.m_aprob, 1) OVER s AS m_aprob_1, LAG(c.m_aprob, 2) OVER s AS m_aprob_2, LAG(c.m_rech, 1) OVER s AS m_rech_1, LAG(c.m_rech, 2) OVER s AS m_rech_2, LAG(c.m_err, 1) OVER s AS m_err_1, LAG(c.m_err, 2) OVER s AS m_err_2, LAG(c.m_lat, 1) OVER s AS m_lat_1, LAG(c.m_lat, 2) OVER s AS m_lat_2 FROM c WINDOW s AS (PARTITION BY c.ambiente, c.cliente_id, c.servicio_id, c.producto_id, c.canal_id, c.moneda_id, c.duracion_ventana_minutos ORDER BY c.ventana_inicio) ), x AS ( SELECT t.*, k.column1 AS tipo, k.column2 AS tipo_previsto, k.column3 AS metrica, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.m_vol WHEN 'RIESGO_APROBACION_BAJA' THEN t.m_aprob WHEN 'RIESGO_RECHAZO_ALTO' THEN t.m_rech WHEN 'RIESGO_ERROR_ALTO' THEN t.m_err ELSE t.m_lat END AS m, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.m_vol_1 WHEN 'RIESGO_APROBACION_BAJA' THEN t.m_aprob_1 WHEN 'RIESGO_RECHAZO_ALTO' THEN t.m_rech_1 WHEN 'RIESGO_ERROR_ALTO' THEN t.m_err_1 ELSE t.m_lat_1 END AS m1, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.m_vol_2 WHEN 'RIESGO_APROBACION_BAJA' THEN t.m_aprob_2 WHEN 'RIESGO_RECHAZO_ALTO' THEN t.m_rech_2 WHEN 'RIESGO_ERROR_ALTO' THEN t.m_err_2 ELSE t.m_lat_2 END AS m2, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.cantidad_total WHEN 'RIESGO_APROBACION_BAJA' THEN ROUND(t.aprob, 4) WHEN 'RIESGO_RECHAZO_ALTO' THEN ROUND(t.rech, 4) WHEN 'RIESGO_ERROR_ALTO' THEN ROUND(t.err, 4) ELSE t.lat END AS valor_observado, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.cantidad_total_esperada WHEN 'RIESGO_APROBACION_BAJA' THEN t.tasa_aprobacion_esperada WHEN 'RIESGO_RECHAZO_ALTO' THEN t.tasa_rechazo_esperada WHEN 'RIESGO_ERROR_ALTO' THEN t.tasa_error_esperada ELSE t.tiempo_respuesta_esperado END AS valor_esperado, CASE k.column1 WHEN 'RIESGO_VOLUMEN_BAJO' THEN t.cantidad_total_minima WHEN 'RIESGO_APROBACION_BAJA' THEN t.tasa_aprobacion_minima WHEN 'RIESGO_RECHAZO_ALTO' THEN t.tasa_rechazo_maxima WHEN 'RIESGO_ERROR_ALTO' THEN t.tasa_error_maxima ELSE t.tiempo_respuesta_maximo END AS umbral FROM t CROSS JOIN (VALUES ('RIESGO_VOLUMEN_BAJO', 'VOLUMEN_BAJO', 'cantidad_total'), ('RIESGO_APROBACION_BAJA', 'APROBACION_BAJA', 'tasa_aprobacion'), ('RIESGO_RECHAZO_ALTO', 'RECHAZO_ALTO', 'tasa_rechazo'), ('RIESGO_ERROR_ALTO', 'ERROR_ALTO', 'tasa_error'), ('RIESGO_LATENCIA_ALTA', 'LATENCIA_ALTA', 'tiempo_respuesta_promedio') ) AS k ), senal AS ( SELECT x.*, CASE WHEN x.m + (x.m - x.m2) / 2 >= 1 THEN 'ALTA' ELSE 'MEDIA' END AS severidad, CAST(strftime('%s', x.ventana_inicio) AS INTEGER) / (60 * x.duracion_ventana_minutos) - ROW_NUMBER() OVER (PARTITION BY x.ambiente, x.cliente_id, x.servicio_id, x.producto_id, x.canal_id, x.moneda_id, x.duracion_ventana_minutos, x.tipo ORDER BY x.ventana_inicio) AS grupo FROM x WHERE ROUND((julianday(x.ventana_inicio) - julianday(x.ventana_inicio_2)) * 1440) = 2 * x.duracion_ventana_minutos AND COALESCE(x.m_vol, 0) < 1 AND COALESCE(x.m_aprob, 0) < 1 AND COALESCE(x.m_rech, 0) < 1 AND COALESCE(x.m_err, 0) < 1 AND COALESCE(x.m_lat, 0) < 1 AND x.m >= 0.5 AND x.m - x.m1 >= 0.1 AND x.m1 - x.m2 >= 0.1 AND x.m + (x.m - x.m2) >= 1 ), ep AS ( SELECT s.*, MIN(s.ventana_inicio) OVER g AS inicio, COUNT(*) OVER g AS ventanas, MAX(s.m) OVER g AS margen_max, ROW_NUMBER() OVER (PARTITION BY s.ambiente, s.cliente_id, s.servicio_id, s.producto_id, s.canal_id, s.moneda_id, s.duracion_ventana_minutos, s.tipo, s.grupo ORDER BY s.ventana_inicio DESC) AS desde_el_final FROM senal s WINDOW g AS (PARTITION BY s.ambiente, s.cliente_id, s.servicio_id, s.producto_id, s.canal_id, s.moneda_id, s.duracion_ventana_minutos, s.tipo, s.grupo) ), cruce AS ( SELECT ep.*, (SELECT MIN(a.ventana_fin) FROM alertas_historico a WHERE a.ambiente = ep.ambiente AND a.cliente_id = ep.cliente_id AND a.servicio_id = ep.servicio_id AND a.producto_id = ep.producto_id AND a.canal_id = ep.canal_id AND a.moneda_id = ep.moneda_id AND a.duracion_ventana_minutos = ep.duracion_ventana_minutos AND a.tipo_alerta = ep.tipo_previsto AND a.ventana_inicio > ep.inicio AND julianday(a.ventana_inicio) <= julianday(ep.ventana_fin) + 60 / 1440.0 ) AS alerta_real_ventana_fin FROM ep WHERE ep.desde_el_final = 1 ) SELECT cruce.tipo AS tipo_prealerta, cruce.tipo_previsto, cruce.ambiente, cruce.cliente_id, cruce.servicio_id, cruce.producto_id, cruce.canal_id, cruce.moneda_id, cruce.duracion_ventana_minutos, cruce.metrica, cruce.inicio, cruce.ventana_inicio AS ultima_ventana, cruce.ventanas, cruce.severidad, cruce.valor_observado, cruce.valor_esperado, cruce.umbral, ROUND(cruce.m, 2) AS margen_consumido, ROUND(cruce.margen_max, 2) AS margen_consumido_max, CASE cruce.severidad WHEN 'ALTA' THEN 1 ELSE 2 END * cruce.duracion_ventana_minutos AS minutos_estimados, CASE WHEN cruce.ventana_inicio = cruce.ultima_ventana_serie AND cruce.alerta_real_ventana_fin IS NULL AND julianday(cruce.ventana_fin) >= prm.ahora_jd - 3 * cruce.duracion_ventana_minutos / 1440.0 THEN 1 ELSE 0 END AS activa, CASE WHEN cruce.alerta_real_ventana_fin IS NOT NULL THEN 'CONFIRMADA' WHEN prm.ahora_jd < julianday(cruce.ventana_fin) + 60 / 1440.0 THEN 'EN_OBSERVACION' ELSE 'NO_SE_CUMPLIO' END AS resultado, cruce.alerta_real_ventana_fin, ROUND((julianday(cruce.alerta_real_ventana_fin) - julianday(cruce.inicio) - cruce.duracion_ventana_minutos / 1440.0) * 1440) AS minutos_anticipacion FROM cruce CROSS JOIN prm;
